var rounds=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.ExcavationRounds>();var p=rounds.player;var e=rounds.equipment;var prod=rounds.production;var ui=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.QuarryOptionalTasks>();var guide=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.QuarryGuidance>();var upgrade=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MinerUpgradeArea>();
var rocks=UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(FindObjectsSortMode.None).Where(r=>r.naturalBoulder&&r.resourceType==0).OrderBy(r=>r.blockId).Take(2).ToArray();if(rocks.Length!=2)throw new System.Exception("Need two starter iron rocks");
