 if(stage==5&&(e.TrucksCompleted>=2||Time.time-deliveryStart>50)){check(e.TrucksCompleted==2&&e.Snapshot.taskDeliveries==2&&(e.Snapshot.taskClaimedMask&4)!=0,"Two actual truck dispatches complete delivery task");check(e.Cash==85,"Cash equals $50 deliveries + $15 refinery + $20 task after pickaxe purchase");ui.Refresh();check(ui.rows.All(r=>r.text.Contains("[DONE]")),"HUD shows all optional tasks completed");var disk=new Bulldozer.Player.Persistence.MiningProgressStore(e.SavePath).Current;check(disk.taskClaimedMask==7&&disk.coins==85&&disk.damageLevel==1,"All rewards and upgrade persisted once");check(!rounds.TryComplete(),"Optional completion does not skip the remaining quarry");System.IO.File.WriteAllLines("Maintenance/Miner/balance-play-verification.txt",report);EditorApplication.update-=tick;Time.captureDeltaTime=0;return;}
